"""Migration for Meridian CRM AUD_EVENT rows."""

from __future__ import annotations


def migrate_event(row: dict) -> dict:
    """Convert one legacy AUD_EVENT row into a modern audit event."""
    timestamp = row["EVT_TS"]
    return {
        "evt_id": int(row["EVT_ID"]),
        "ts": (
            f"{timestamp[0:4]}-{timestamp[4:6]}-{timestamp[6:8]}"
            f"T{timestamp[8:10]}:{timestamp[10:12]}:{timestamp[12:14]}"
        ),
        "code": row["EVT_CD"],
        "user_id": row["USR_ID"],
        "entity": row["ENT_NAME"],
        "entity_id": row["ENT_ID"],
        "old_val": row["OLD_VAL"],
        "new_val": row["NEW_VAL"],
    }


class AuditStore:
    """An append-only in-memory audit event store."""

    __slots__ = ("__events", "__evt_ids")

    def __init__(self) -> None:
        self.__events: list[dict] = []
        self.__evt_ids: set[int] = set()

    def append(self, event: dict) -> None:
        stored_event = event.copy()
        self.__events.append(stored_event)
        self.__evt_ids.add(stored_event["evt_id"])

    def events(self) -> list[dict]:
        return [event.copy() for event in self.__events]

    def __len__(self) -> int:
        return len(self.__events)

    def _has_evt_id(self, evt_id: int) -> bool:
        return evt_id in self.__evt_ids


def migrate(rows: list[dict], store: AuditStore | None = None) -> AuditStore:
    """Migrate rows in canonical EVT_ID order without duplicating stored events."""
    if store is None:
        store = AuditStore()

    for row in sorted(rows, key=lambda item: int(item["EVT_ID"])):
        event = migrate_event(row)
        if not store._has_evt_id(event["evt_id"]):
            store.append(event)

    return store
